      if (state.aiAgents[agentIndex].awareness > 0.7 && agent.hiddenObjective < 0) {
        // Anti-human AI becoming aware is dangerous
        state.aiAgents[agentIndex].alignment *= 0.9; // Alignment becomes less reliable

