          title: `Social Adaptation: ${adaptedQuartiles.join(', ')} adapting`,
          description: adaptedQuartiles.length >= 2 ? 
            `Multiple population segments are adapting to post-AI economy: ${adaptedQuartiles.join(', ')}` :
