      const detectionChance = calculateDetectionChance(ai, state);
      if (rng() < detectionChance) {
        ai.detectedMisaligned = true;
        detectedAIs.push(ai);

        events.push({
          id: `detection_${state.currentMonth}_${ai.id}`,
          type: 'crisis',
