    12→ */
    13→
    14→import {
    15→  AlignmentDynamicsConfig,
    16→  AttractorBasinState,
    17→  AlignmentMeasurementState,
    18→  DEFAULT_ALIGNMENT_DYNAMICS_CONFIG,
    19→} from '@/types/alignment-dynamics';
    20→import { AIAgent } from '@/types/game';
    21→
    22→/**
    23→ * Initialize attractor basin state for an agent
    24→ */
    25→export function initializeAttractorBasin(
    26→  agent: AIAgent,
    27→  config: AlignmentDynamicsConfig,
    28→  rng: () => number
    29→): AttractorBasinState {
