    50→}
    51→
    52→/**
    53→ * Initialize measurement state for an agent
    54→ */
    55→export function initializeAlignmentMeasurement(
    56→  agent: AIAgent,
    57→  config: AlignmentDynamicsConfig
    58→): AlignmentMeasurementState {
    59→  const unknowableConfig = config.unknowable;
    60→
    61→  // Is this agent above the unknowability threshold?
    62→  const isAboveThreshold = agent.capability >= unknowableConfig.capabilityThreshold;
    63→
    64→  // Calculate initial noise level
    65→  const noiseLevel = isAboveThreshold
    66→    ? unknowableConfig.measurementNoise
    67→    : 0.1; // Low noise for measurable AIs
    68→
    69→  // Measured alignment = true alignment + noise (initially)
    70→  const measuredAlignment = agent.trueAlignment;
    71→
    72→  return {
    73→    trueAlignment: agent.trueAlignment,
    74→    measuredAlignment,
    75→    confidence: isAboveThreshold ? 0.2 : 0.9,
    76→    noiseLevel,
    77→    isHidden: isAboveThreshold && unknowableConfig.trueAlignmentHidden,
    78→  };
    79→}
    80→
    81→/**
    82→ * Update epicycle dynamics (oscillation around attractor)
    83→ *
    84→ * Physics analogy: Ball in a valley
    85→ * - Restoring force pulls toward attractor (gravity)
    86→ * - External forces perturb position (wind)
    87→ * - Velocity creates oscillation (momentum)
    88→ */
    89→export function updateEpicycleDynamics(
    90→  agent: AIAgent,
    91→  basinState: AttractorBasinState,
    92→  config: AlignmentDynamicsConfig,
    93→  externalPerturbation: number, // External forces (control, environment)
    94→  rng: () => number,
    95→  deltaTime: number = 1 // Months
    96→): AttractorBasinState {
    97→  const epicycleConfig = config.epicycles;
    98→
    99→  if (!epicycleConfig.enabled) {
   100→    return basinState; // No change if disabled
   101→  }
