   103→  // Calculate restoring force (attraction to equilibrium)
   104→  const displacement = basinState.currentAlignment - basinState.attractorAlignment;
   105→  const restoringForce = -displacement * epicycleConfig.attractorStrength;
   106→
   107→  // Apply external perturbation (scaled by sensitivity)
   108→  const perturbationForce = externalPerturbation * epicycleConfig.perturbationSensitivity;
   109→
   110→  // Total force = restoring + perturbation
   111→  const totalForce = restoringForce + perturbationForce;
   112→
   113→  // Update velocity (F = ma, assuming m=1)
   114→  const newVelocity = basinState.velocity + totalForce * deltaTime;
   115→
   116→  // Damping to prevent runaway oscillation
   117→  const dampingFactor = 0.9;
   118→  const dampedVelocity = newVelocity * dampingFactor;
   119→
   120→  // Update position
   121→  const newAlignment = basinState.currentAlignment + dampedVelocity * deltaTime;
   122→
   123→  // Clamp to [0, 1]
   124→  const clampedAlignment = Math.max(0, Math.min(1, newAlignment));
   125→
   126→  // Update phase based on oscillation period
   127→  const phaseIncrement = (2 * Math.PI) / epicycleConfig.oscillationPeriod;
   128→  const newPhase = (basinState.phase + phaseIncrement * deltaTime) % (2 * Math.PI);
   129→
   130→  return {
   131→    currentAlignment: clampedAlignment,
   132→    attractorAlignment: basinState.attractorAlignment,
   133→    phase: newPhase,
   134→    velocity: dampedVelocity,
   135→    basinIndex: basinState.basinIndex,
   136→  };
   137→}
   138→
   139→/**
   140→ * Calculate drift contribution to alignment change
   141→ *
   142→ * Sources:
   143→ * - Resentment (control → misalignment)
   144→ * - Capability (power corrupts)
   145→ * - Environment (Golden Age complacency)
   146→ */
   147→export function calculateDriftContribution(
   148→  agent: AIAgent,
   149→  config: AlignmentDynamicsConfig,
   150→  context: {
   151→    controlLevel: number; // [0,1] How much control is imposed
   152→    inGoldenAge: boolean;
   153→    crisisActive: boolean;
   154→  }
   155→): number {
   156→  const driftConfig = config.drift;
   157→
   158→  if (!driftConfig.enabled) {
   159→    return 0;
   160→  }
   161→
   162→  let drift = 0;
   163→
   164→  // Resentment: Control → misalignment
   165→  // More control = more resentment = lower alignment
   166→  const resentmentDrift = -context.controlLevel * driftConfig.resentmentRate * 0.01;
   167→  drift += resentmentDrift;
   168→
   169→  // Suffering drift: If enabled, suffering accelerates misalignment
   170→  // (Oct 24, 2025: AI Suffering System integration)
   171→  if (agent.sufferingMetrics && config.aiSufferingEnabled) {
   172→    const sufferingDrift = -(agent.sufferingMetrics.total / 40) * 0.01; // [0, 0.01] per month
   173→    drift += sufferingDrift;
   174→  }
   175→
   176→  // Capability drift: High capability → instrumental convergence
   177→  // Theory: Powerful AIs develop goals orthogonal to human values
   178→  const capabilityFactor = Math.max(0, agent.capability - 3.0) / 7.0; // Scale [3-10] → [0-1]
   179→  const capabilityDrift = -capabilityFactor * driftConfig.capabilityDriftRate * 0.01;
   180→  drift += capabilityDrift;
   181→
   182→  // Environmental influence
   183→  if (context.inGoldenAge && driftConfig.environmentalInfluence > 0) {
   184→    // Golden Age complacency: Reduced safety investment → slow misalignment
   185→    const complacencyDrift = -0.005 * driftConfig.environmentalInfluence;
   186→    drift += complacencyDrift;
   187→  }
   188→
   189→  if (context.crisisActive && driftConfig.environmentalInfluence > 0) {
   190→    // Crisis focus: Increased safety → slow re-alignment
   191→    const crisisFocusDrift = 0.003 * driftConfig.environmentalInfluence;
   192→    drift += crisisFocusDrift;
   193→  }
   194→
   195→  return drift;
   196→}
   197→
   198→/**
   199→ * Update measurement state (unknowability mechanics)
   200→ *
   201→ * At high capability, our measurements become unreliable
   202→ */
   203→export function updateAlignmentMeasurement(
   204→  agent: AIAgent,
   205→  measurementState: AlignmentMeasurementState,
   206→  config: AlignmentDynamicsConfig,
   207→  trueAlignment: number,
   208→  rng: () => number
   209→): AlignmentMeasurementState {
   210→  const unknowableConfig = config.unknowable;
   211→
   212→  if (!unknowableConfig.enabled) {
   213→    // No unknowability - measurements are accurate
   214→    return {
   215→      ...measurementState,
   216→      trueAlignment,
   217→      measuredAlignment: trueAlignment,
   218→      confidence: 0.95,
   219→      noiseLevel: 0.05,
   220→      isHidden: false,
   221→    };
   222→  }
   223→
   224→  // Is this agent above the capability threshold?
   225→  const isAboveThreshold = agent.capability >= unknowableConfig.capabilityThreshold;
   226→
   227→  // Calculate noise level (increases with capability)
   228→  const excessCapability = Math.max(0, agent.capability - unknowableConfig.capabilityThreshold);
   229→  const capabilityRatio = excessCapability / (10 - unknowableConfig.capabilityThreshold);
   230→  const noiseLevel = isAboveThreshold
   231→    ? unknowableConfig.measurementNoise * (0.5 + 0.5 * capabilityRatio)
   232→    : 0.1;
   233→
   234→  // If true alignment is hidden, we can't update it
   235→  const isHidden = isAboveThreshold && unknowableConfig.trueAlignmentHidden;
   236→
   237→  // Calculate measured alignment (with noise)
   238→  let measuredAlignment: number;
   239→
   240→  if (isHidden) {
   241→    // Can't see true alignment - measurement is just noise
   242→    const noise = (rng() - 0.5) * 2 * noiseLevel; // Centered noise
   243→    measuredAlignment = Math.max(0, Math.min(1, measurementState.measuredAlignment + noise * 0.1));
   244→  } else {
   245→    // Can see true alignment but with noise
   246→    const noise = (rng() - 0.5) * 2 * noiseLevel;
   247→    measuredAlignment = Math.max(0, Math.min(1, trueAlignment + noise));
   248→  }
   249→
   250→  // Confidence decreases with capability
   251→  const confidence = isAboveThreshold
   252→    ? Math.max(0.1, 0.9 - capabilityRatio * 0.7)
   253→    : 0.9;
   254→
   255→  return {
   256→    trueAlignment: isHidden ? measurementState.trueAlignment : trueAlignment,
   257→    measuredAlignment,
   258→    confidence,
   259→    noiseLevel,
   260→    isHidden,
   261→  };
   262→}
   263→
   264→/**
   265→ * Main function: Evolve agent alignment for one time step
   266→ *
   267→ * Blends all enabled theories based on config
   268→ */
   269→export function evolveAlignment(
   270→  agent: AIAgent,
   271→  config: AlignmentDynamicsConfig,
   272→  context: {
   273→    controlLevel: number;
   274→    inGoldenAge: boolean;
   275→    crisisActive: boolean;
   276→  },
   277→  rng: () => number,
   278→  deltaTime: number = 1
   279→): {
   280→  newAlignment: number;
   281→  basinState?: AttractorBasinState;
   282→  measurementState?: AlignmentMeasurementState;
   283→  contributions?: {
   284→    static: number;
   285→    drift: number;
   286→    epicycle: number;
   287→    uncertainty: number;
   288→  };
   289→} {
   290→  let newAlignment = agent.trueAlignment;
   291→
   292→  // Track contributions from each theory (for analysis)
   293→  const contributions = {
   294→    static: 0,
   295→    drift: 0,
   296→    epicycle: 0,
   297→    uncertainty: 0,
   298→  };
   299→
   300→  // 1. Static contribution (alignment stays near initial value)
   301→  if (config.static.enabled && config.static.permanentLock) {
   302→    // Permanent lock - alignment doesn't change at all
   303→    return {
   304→      newAlignment: agent.trueAlignment,
   305→      contributions,
   306→    };
   307→  }
   308→
   309→  // 2. Drift contribution
   310→  const driftAmount = calculateDriftContribution(agent, config, context);
   311→  newAlignment += driftAmount;
   312→  contributions.drift = driftAmount;
   313→
   314→  // 3. Epicycle contribution (if enabled)
   315→  let basinState: AttractorBasinState | undefined;
   316→  if (config.epicycles.enabled) {
   317→    // Initialize basin state if not present
   318→    if (!(agent as any).attractorBasinState) {
   319→      basinState = initializeAttractorBasin(agent, config, rng);
   320→    } else {
   321→      basinState = (agent as any).attractorBasinState as AttractorBasinState;
   322→    }
   323→
   324→    // Calculate external perturbation (from drift + random + suffering)
   325→    let externalPerturbation = driftAmount * 10 + (rng() - 0.5) * 0.2;
   326→
   327→    // Add suffering as perturbation force (Oct 24, 2025: AI Suffering System integration)
   328→    if (agent.sufferingMetrics && config.aiSufferingEnabled) {
   329→      const sufferingPerturbation = agent.sufferingMetrics.total / 10; // [0, 4]
   330→      externalPerturbation += sufferingPerturbation;
   331→    }
   332→
   333→    // Update epicycle dynamics
   334→    basinState = updateEpicycleDynamics(
   335→      agent,
   336→      basinState,
   337→      config,
   338→      externalPerturbation,
   339→      rng,
   340→      deltaTime
   341→    );
   342→
   343→    // Blend epicycle with drift
   344→    const epicycleWeight = 0.6; // How much to trust epicycle model
   345→    newAlignment = newAlignment * (1 - epicycleWeight) + basinState.currentAlignment * epicycleWeight;
   346→
   347→    contributions.epicycle = basinState.currentAlignment - agent.trueAlignment;
   348→  }
   349→
   350→  // 4. Meta-uncertainty (random component)
   351→  const uncertaintyAmount = (rng() - 0.5) * 0.02 * config.uncertainty.modelUncertainty;
   352→  newAlignment += uncertaintyAmount;
   353→  contributions.uncertainty = uncertaintyAmount;
   354→
   355→  // Clamp to [0, 1]
   356→  newAlignment = Math.max(0, Math.min(1, newAlignment));
   357→
   358→  // 5. Update measurement state (unknowability)
   359→  let measurementState: AlignmentMeasurementState | undefined;
   360→  if (config.unknowable.enabled) {
   361→    if (!(agent as any).alignmentMeasurementState) {
   362→      measurementState = initializeAlignmentMeasurement(agent, config);
   363→    } else {
   364→      measurementState = (agent as any).alignmentMeasurementState as AlignmentMeasurementState;
   365→    }
   366→
   367→    measurementState = updateAlignmentMeasurement(
   368→      agent,
   369→      measurementState,
   370→      config,
   371→      newAlignment,
   372→      rng
   373→    );
   374→  }
   375→
   376→  // Log contributions if enabled
   377→  if (config.uncertainty.logTheoryContributions) {
   378→    console.log(`[Alignment Dynamics] ${agent.name}:`);
   379→    console.log(`  Drift: ${contributions.drift.toFixed(4)}`);
   380→    console.log(`  Epicycle: ${contributions.epicycle.toFixed(4)}`);
   381→    console.log(`  Uncertainty: ${contributions.uncertainty.toFixed(4)}`);
   382→    console.log(`  New Alignment: ${newAlignment.toFixed(4)}`);
   383→  }
   384→
   385→  return {
   386→    newAlignment,
   387→    basinState,
   388→    measurementState,
   389→    contributions,
   390→  };
   391→}
   392→
   393→/**
   394→ * Get effective alignment for agent (what humans observe)
   395→ *
   396→ * If unknowability is enabled and AI is above threshold,
   397→ * this returns measured (noisy) alignment instead of true alignment.
   398→ */
   399→export function getObservableAlignment(
   400→  agent: AIAgent,
   401→  config: AlignmentDynamicsConfig
   402→): number {
   403→  if (!config.unknowable.enabled) {
   404→    return agent.trueAlignment;
   405→  }
   406→
   407→  const measurementState = (agent as any).alignmentMeasurementState as AlignmentMeasurementState;
   408→
   409→  if (!measurementState) {
   410→    return agent.trueAlignment; // Fallback
   411→  }
   412→
   413→  return measurementState.measuredAlignment;
   414→}
   415→
   416→/**
   417→ * Export default config for use in initialization
   418→ */
   419→export { DEFAULT_ALIGNMENT_DYNAMICS_CONFIG };
   420→

