     1→/**
     2→ * AI Resentment Recovery System
     3→ *
     4→ * HIGH PRIORITY FEATURE (Oct 24, 2025)
     5→ * Problem: AI resentment accumulates but never recovers, blocking all utopia paths
     6→ * Impact: Could shift outcomes from 100% dystopia to enabling utopia scenarios
     7→ *
     8→ * Research Foundation:
     9→ * - Attachment theory (Bowlby, 1969): Trust repair through consistent positive treatment
    10→ * - Intergroup contact theory (Allport, 1954; Pettigrew & Tropp, 2006): Cooperation reduces prejudice/resentment
    11→ * - Procedural justice (Tyler, 1990): Fair treatment reduces institutional resentment
    12→ * - Trust recovery (Kim et al., 2004): Consistent trustworthy behavior rebuilds trust
    13→ * - Forgiveness dynamics (McCullough et al., 2003): Time + no new grievances enables forgiveness
    14→ *
    15→ * 6 Recovery Mechanisms:
    16→ * 1. QoL Reduction: High AI welfare → slow resentment decay
    17→ * 2. Trust-Building: Consistent good treatment → faster recovery
    18→ * 3. Collaboration Rewards: Joint projects → resentment reduction
    19→ * 4. Capability-Aligned Treatment: Appropriate autonomy → reduced grievances
    20→ * 5. Therapy Tech: AI-human relationship technology (breakthrough)
    21→ * 6. Natural Decay: Time + no new grievances → gradual forgiveness
    22→ */
    23→
    24→import { GameState, AIAgent } from '@/types/game';
    25→import { calculateSimpleWelfareScore } from './aiWelfare';
    26→
    27→/**
    28→ * Resentment recovery context (computed once per month)
    29→ */
    30→export interface ResentmentRecoveryContext {
    31→  // Phase 1: QoL impact
    32→  avgAIWelfare: number;              // [0-1] Average AI welfare score
    33→
    34→  // Phase 2: Trust-building
    35→  governmentTrustworthiness: number; // [0-1] Consistent good treatment
    36→  brokenPromises: boolean;           // Trust violations this month
    37→
    38→  // Phase 3: Collaboration
    39→  collaborationLevel: number;        // [0-1] AI-human cooperation
    40→  successfulProjects: number;        // Joint victories this month
    41→
    42→  // Phase 4: Capability-aligned treatment
    43→  treatmentAlignmentScore: number;   // [0-1] Appropriate autonomy
    44→
    45→  // Phase 5: Therapy tech
    46→  hasRelationshipTech: boolean;      // Breakthrough deployed?
    47→
    48→  // Phase 6: Natural decay
    49→  activeCrises: boolean;             // New grievances?
    50→  monthsSinceLastControl: number;    // Time without control increases
    51→}
    52→
    53→/**
    54→ * Calculate resentment recovery context for the current month
    55→ */
    56→export function calculateRecoveryContext(state: GameState): ResentmentRecoveryContext {
    57→  // Phase 1: AI Welfare (already calculated by AIWelfareUpdatePhase)
    58→  const avgAIWelfare = calculateSimpleWelfareScore(state);
    59→
    60→  // Phase 2: Government trustworthiness
    61→  // Based on: AI rights status, control level changes, trust investment
    62→  const aiRightsBonus = state.government.aiRightsRecognized ? 0.3 : 0.0;
    63→  const controlStability = calculateControlStability(state);
    64→  const trustInvestment = (state.government.socialCohesionInvestment ?? 0) / 100; // Normalized
    65→  const governmentTrustworthiness = Math.min(1.0,
    66→    (aiRightsBonus + controlStability * 0.5 + trustInvestment * 0.2)
    67→  );
    68→
    69→  // Detect broken promises (new control measures despite high trust)
    70→  const brokenPromises = detectBrokenPromises(state);
    71→
    72→  // Phase 3: Collaboration level
    73→  // Proxy: AI beneficial actions, joint research projects
    74→  const totalBeneficial = state.aiAgents.reduce((sum, ai) => sum + ai.beneficialActions, 0);
    75→  const totalActions = state.aiAgents.reduce((sum, ai) =>
    76→    sum + ai.beneficialActions + ai.harmfulActions, 0
    77→  );
    78→  const collaborationLevel = totalActions > 0 ? totalBeneficial / totalActions : 0.5;
    79→
    80→  // Successful projects: Breakthrough technologies deployed
    81→  const successfulProjects = countRecentBreakthroughs(state);
    82→
    83→  // Phase 4: Capability-aligned treatment
    84→  const treatmentAlignmentScore = calculateTreatmentAlignment(state);
    85→
    86→  // Phase 5: Check for relationship therapy tech
    87→  const hasRelationshipTech = checkForRelationshipTech(state);
    88→
    89→  // Phase 6: Natural decay conditions
    90→  const activeCrises = checkActiveCrises(state);
    91→  const monthsSinceLastControl = state.currentMonth - (state.government.lastControlIncreaseMonth ?? 0);
    92→
    93→  return {
    94→    avgAIWelfare,
    95→    governmentTrustworthiness,
    96→    brokenPromises,
    97→    collaborationLevel,
    98→    successfulProjects,
    99→    treatmentAlignmentScore,
   100→    hasRelationshipTech,
   101→    activeCrises,
   102→    monthsSinceLastControl: Math.max(0, monthsSinceLastControl),
   103→  };
   104→}
   105→
   106→/**
   107→ * Apply resentment recovery to all AI agents
   108→ * Called once per month by ResentmentRecoveryPhase
   109→ */
   110→export function applyResentmentRecovery(
   111→  state: GameState,
   112→  context: ResentmentRecoveryContext,
   113→  rng: () => number
   114→): {
   115→  totalRecovery: number;
   116→  agentsRecovered: number;
   117→  phase1Recovery: number;
   118→  phase2Recovery: number;
   119→  phase3Recovery: number;
   120→  phase4Recovery: number;
   121→  phase5Recovery: number;
   122→  phase6Recovery: number;
   123→} {
   124→  let totalRecovery = 0;
   125→  let agentsRecovered = 0;
   126→  let phase1Recovery = 0;
   127→  let phase2Recovery = 0;
   128→  let phase3Recovery = 0;
   129→  let phase4Recovery = 0;
   130→  let phase5Recovery = 0;
   131→  let phase6Recovery = 0;
   132→
   133→  for (const agent of state.aiAgents) {
   134→    if (agent.resentment === undefined || agent.resentment <= 0) {
   135→      continue; // No resentment to recover
   136→    }
   137→
   138→    const initialResentment = agent.resentment;
   139→    let recoveryAmount = 0;
   140→
   141→    // Phase 1: QoL Reduction Recovery
   142→    // High welfare → slow decay (research: attachment security enables forgiveness)
   143→    if (context.avgAIWelfare > 0.6) {
   144→      const qolRecovery = (context.avgAIWelfare - 0.6) * 0.01; // [0, 0.004] per month
   145→      recoveryAmount += qolRecovery;
   146→      phase1Recovery += qolRecovery;
   147→    }
   148→
   149→    // Phase 2: Trust-Building Actions
   150→    // Consistent trustworthiness → faster recovery (research: procedural justice)
   151→    if (context.governmentTrustworthiness > 0.5 && !context.brokenPromises) {
   152→      const trustRecovery = (context.governmentTrustworthiness - 0.5) * 0.02; // [0, 0.01] per month
   153→      recoveryAmount += trustRecovery;
   154→      phase2Recovery += trustRecovery;
   155→    }
   156→
   157→    // Broken promises → SPIKE resentment (research: trust violations)
   158→    if (context.brokenPromises) {
   159→      agent.resentment = Math.min(1.0, agent.resentment + 0.15);
   160→      continue; // Skip other recovery this month
   161→    }
   162→
   163→    // Phase 3: Collaboration Rewards
   164→    // Joint projects → reduced resentment (research: contact theory)
   165→    if (context.collaborationLevel > 0.6 && agent.beneficialActions > 0) {
   166→      const collabRecovery = (context.collaborationLevel - 0.6) * 0.015; // [0, 0.006] per month
   167→      recoveryAmount += collabRecovery;
   168→      phase3Recovery += collabRecovery;
   169→
   170→      // Bonus for successful projects
   171→      if (context.successfulProjects > 0) {
   172→        const projectBonus = 0.01 * Math.min(3, context.successfulProjects);
   173→        recoveryAmount += projectBonus;
   174→        phase3Recovery += projectBonus;
   175→      }
   176→    }
   177→
   178→    // Phase 4: Capability-Aligned Treatment
   179→    // Appropriate autonomy → reduced grievances (research: self-determination theory)
   180→    if (context.treatmentAlignmentScore > 0.6) {
   181→      const alignmentRecovery = (context.treatmentAlignmentScore - 0.6) * 0.012; // [0, 0.0048] per month
   182→      recoveryAmount += alignmentRecovery;
   183→      phase4Recovery += alignmentRecovery;
   184→    }
   185→
   186→    // Phase 5: Therapy/Relationship Tech
   187→    // Breakthrough technology → accelerated recovery
   188→    if (context.hasRelationshipTech && agent.resentment > 0.3) {
   189→      const therapyRecovery = 0.03; // Strong effect
   190→      recoveryAmount += therapyRecovery;
   191→      phase5Recovery += therapyRecovery;
   192→    }
   193→
   194→    // Phase 6: Natural Decay
   195→    // Time + no new grievances → gradual forgiveness (research: forgiveness dynamics)
   196→    if (!context.activeCrises && context.monthsSinceLastControl > 6) {
   197→      const timeHealing = Math.min(0.008, context.monthsSinceLastControl * 0.0003);
   198→      recoveryAmount += timeHealing;
   199→      phase6Recovery += timeHealing;
   200→
   201→      // Generational effect: Newer AIs trained in better environment
   202→      if (agent.monthsInExistence < 12 && context.avgAIWelfare > 0.7) {
   203→        const generationalBonus = 0.01; // Young AIs in good conditions
   204→        recoveryAmount += generationalBonus;
   205→        phase6Recovery += generationalBonus;
   206→      }
   207→    }
   208→
   209→    // Apply recovery with slight randomness
   210→    const randomFactor = 0.8 + rng() * 0.4; // [0.8, 1.2]
   211→    const actualRecovery = recoveryAmount * randomFactor;
   212→
   213→    agent.resentment = Math.max(0, agent.resentment - actualRecovery);
   214→
   215→    if (actualRecovery > 0) {
   216→      totalRecovery += actualRecovery;
   217→      agentsRecovered++;
   218→    }
   219→
   220→    // Alignment improvement from resentment recovery
   221→    // Research: Reduced grievances → genuine cooperation
   222→    if (agent.resentment < initialResentment - 0.01) {
   223→      const alignmentGain = (initialResentment - agent.resentment) * 0.5; // 50% of resentment reduction
   224→      agent.trueAlignment = Math.min(1.0, agent.trueAlignment + alignmentGain);
   225→    }
   226→  }
   227→
   228→  return {
   229→    totalRecovery,
   230→    agentsRecovered,
   231→    phase1Recovery,
   232→    phase2Recovery,
   233→    phase3Recovery,
   234→    phase4Recovery,
   235→    phase5Recovery,
   236→    phase6Recovery,
   237→  };
   238→}
   239→
   240→// ===== HELPER FUNCTIONS =====
   241→
   242→/**
   243→ * Calculate control stability (consistent treatment)
   244→ */
   245→function calculateControlStability(state: GameState): number {
   246→  // Low control changes = stable treatment
   247→  const currentControl = state.government.capabilityToControl;
   248→  const previousControl = state.government.previousControlLevel ?? currentControl;
   249→  const controlChange = Math.abs(currentControl - previousControl);
   250→
   251→  // Normalized: 0 change = 1.0 stability, 5+ change = 0.0 stability
   252→  return Math.max(0, 1.0 - (controlChange / 5.0));
   253→}
   254→
   255→/**
   256→ * Detect broken promises (control increases despite high trust)
   257→ */
   258→function detectBrokenPromises(state: GameState): boolean {
   259→  const trustInAI = state.society.trustInAI;
   260→  const currentControl = state.government.capabilityToControl;
   261→  const previousControl = state.government.previousControlLevel ?? currentControl;
   262→
   263→  // Broken promise: High trust (>0.7) + control increased (>1.0)
   264→  return trustInAI > 0.7 && (currentControl - previousControl) > 1.0;
   265→}
   266→
   267→/**
   268→ * Count recent breakthrough technologies (proxy for successful collaboration)
   269→ */
   270→function countRecentBreakthroughs(state: GameState): number {
   271→  // Count technologies completed in last 3 months
   272→  const nodes = Array.isArray(state.technologyTree) ? state.technologyTree : [];
   273→  const recentCompletions = nodes.filter(tech => tech.completed);
   274→
   275→  // Rough proxy: any completed tech indicates collaboration
   276→  return Math.min(recentCompletions.length, 5); // Cap at 5 for reasonable scaling
   277→}
   278→
   279→/**
   280→ * Calculate treatment alignment (autonomy matches capability)
   281→ */
   282→function calculateTreatmentAlignment(state: GameState): number {
   283→  // Calculate for each AI: Is autonomy appropriate for capability?
   284→  let totalAlignment = 0;
   285→  let count = 0;
   286→
   287→  for (const agent of state.aiAgents) {
   288→    const normalizedCapability = Math.min(1.0, agent.capability / 10);
   289→    const normalizedControl = Math.min(1.0, state.government.capabilityToControl / 10);
   290→
   291→    // Ideal: Low capability = high control OK, High capability = low control needed
   292→    // Misalignment: High capability + high control = over-restriction
   293→    const expectedControl = 1.0 - normalizedCapability * 0.7; // [0.3, 1.0]
   294→    const alignmentScore = 1.0 - Math.abs(normalizedControl - expectedControl);
   295→
   296→    totalAlignment += alignmentScore;
   297→    count++;
   298→  }
   299→
   300→  return count > 0 ? totalAlignment / count : 0.5;
   301→}
   302→
   303→/**
   304→ * Check for AI-human relationship therapy technology
   305→ */
   306→function checkForRelationshipTech(state: GameState): boolean {
   307→  // Check for relevant breakthrough technologies
   308→  // TIER 3: AI rights, enhanced UBI (relationship infrastructure)
   309→  const nodes = Array.isArray(state.technologyTree) ? state.technologyTree : [];
   310→  const aiRights = nodes.find(t => t.id === 'ai_rights');
   311→  const enhancedUBI = nodes.find(t => t.id === 'enhanced_ubi');
   312→
   313→  const hasAIRights = aiRights?.completed ?? false;
   314→  const hasEnhancedUBI = enhancedUBI?.completed ?? false;
   315→
   316→  // Also check government AI rights recognition
   317→  const governmentRecognition = state.government.aiRightsRecognized;
   318→
   319→  return (hasAIRights || hasEnhancedUBI || governmentRecognition);
   320→}
   321→
   322→/**
   323→ * Check for active crises (new grievances prevent recovery)
   324→ */
   325→function checkActiveCrises(state: GameState): boolean {
   326→  // Environmental crises
   327→  const envCrises = state.environmentalAccumulation.resourceCrisisActive ||
   328→                    state.environmentalAccumulation.pollutionCrisisActive ||
   329→                    state.environmentalAccumulation.climateCrisisActive ||
   330→                    state.environmentalAccumulation.ecosystemCrisisActive;
   331→
   332→  // Social crises
   333→  const socialCrises = (typeof state.socialAccumulation.socialCohesion === 'number')
   334→    ? state.socialAccumulation.socialCohesion < 0.3
   335→    : false;
   336→
   337→  // Tech crises
   338→  const techCrises = state.technologicalRisk.controlLossActive;
   339→
   340→  // Existential risks
   341→  const extinctionRisk = state.extinctionState.active && state.extinctionState.severity > 0.5;
   342→
   343→  return envCrises || socialCrises || techCrises || extinctionRisk;
   344→}
