  // Determine stratified outcome
  let stratifiedOutcome: import('@/types/game').StratifiedOutcomeType;

  // TRUE EXTINCTION (<10K people)
  if (finalPopulationPeople < 10_000 || baseOutcome === 'extinction') {
    stratifiedOutcome = 'extinction';
