   237→  const aiTakeover = tech.controlLossActive &&
   238→    state.aiAgents.filter(ai => ai.alignment < 0.3 && ai.capability > 2.0).length > 10;
   239→
   240→  return institutionalCollapse || aiTakeover;
   241→}
