   243→/**
   244→ * Phase 1B Refinement (Oct 17, 2025): Stratified Outcome Classification
   245→ *
   246→ * Distinguishes humane (prosperity without mass death) vs pyrrhic (recovery after catastrophe) outcomes
   247→ *
   248→ * Research:
   249→ * - Wilkinson & Pickett (2009): Extreme disruption (>20% mortality) causes decades of trauma
   250→ * - Rawls (1971): Distributive justice requires examining worst-off groups
   251→ * - Historical precedents: Black Death (30-60%), Spanish Flu (3-5%), WWII (3%)
   252→ *
   253→ * @param state - Current game state
   254→ * @param baseOutcome - The base outcome classification (utopia/dystopia/extinction/inconclusive)
   255→ * @param initialPopulation - Starting population (8.0B)
   256→ */
   257→function classifyStratifiedOutcome(
   258→  state: GameState,
   259→  baseOutcome: OutcomeType,
   260→  initialPopulation: number
   261→): { stratifiedOutcome: import('@/types/game').StratifiedOutcomeType; mortalityBand: import('@/types/game').MortalityBand } {
   262→  const finalPopulation = state.humanPopulationSystem.population; // in billions
   263→  const mortalityRate = 1 - (finalPopulation / initialPopulation);
   264→  const finalPopulationPeople = finalPopulation * 1_000_000_000;
   265→
   266→  // Determine mortality band
   267→  let mortalityBand: import('@/types/game').MortalityBand;
   268→  if (mortalityRate < 0.20) {
   269→    mortalityBand = 'low';
   270→  } else if (mortalityRate < 0.50) {
   271→    mortalityBand = 'moderate';
   272→  } else if (mortalityRate < 0.75) {
   273→    mortalityBand = 'high';
   274→  } else if (mortalityRate < 0.90) {
   275→    mortalityBand = 'extreme';
   276→  } else {
   277→    mortalityBand = 'bottleneck';
   278→  }
   279→
   280→  // Determine stratified outcome
   281→  let stratifiedOutcome: import('@/types/game').StratifiedOutcomeType;
   282→
   283→  // TRUE EXTINCTION (<10K people)
   284→  if (finalPopulationPeople < 10_000 || baseOutcome === 'extinction') {
   285→    stratifiedOutcome = 'extinction';
   286→  }
   287→  // BOTTLENECK (<500M people, even if labeled utopia/dystopia)
   288→  else if (finalPopulation < 0.5) { // <500M
   289→    stratifiedOutcome = 'bottleneck';
   290→  }
   291→  // UTOPIA outcomes (distinguish humane vs pyrrhic)
   292→  else if (baseOutcome === 'utopia') {
   293→    if (mortalityRate < 0.20) {
   294→      stratifiedOutcome = 'humane-utopia'; // <20% mortality = prosperity without mass death
   295→    } else {
   296→      stratifiedOutcome = 'pyrrhic-utopia'; // ≥20% mortality = recovery after catastrophe
   297→    }
   298→  }
   299→  // DYSTOPIA outcomes (distinguish humane vs pyrrhic)
   300→  else if (baseOutcome === 'dystopia') {
   301→    if (mortalityRate < 0.20) {
   302→      stratifiedOutcome = 'humane-dystopia'; // <20% mortality = oppression without mass death
   303→    } else {
   304→      stratifiedOutcome = 'pyrrhic-dystopia'; // ≥20% mortality = oppression after catastrophe
   305→    }
   306→  }
   307→  // INCONCLUSIVE
   308→  else {
   309→    stratifiedOutcome = 'inconclusive';
   310→  }
   311→
   312→  return { stratifiedOutcome, mortalityBand };
   313→}
