   315→/**
   316→ * Seedable random number generator for reproducible simulations
   317→ */
   318→export class SeededRandom {
   319→  private seed: number;
   320→  
   321→  constructor(seed: number) {
   322→    this.seed = seed;
   323→  }
   324→  
   325→  /**
   326→   * Generate next random number [0, 1)
   327→   */
   328→  next(): number {
   329→    // Simple LCG (Linear Congruential Generator)
   330→    this.seed = (this.seed * 1664525 + 1013904223) % 2**32;
   331→    return this.seed / 2**32;
   332→  }
   333→  
   334→  /**
   335→   * Generate random number in range [min, max)
   336→   */
   337→  range(min: number, max: number): number {
   338→    return min + this.next() * (max - min);
   339→  }
   340→  
   341→  /**
   342→   * Generate random boolean with given probability
   343→   */
   344→  chance(probability: number): boolean {
   345→    return this.next() < probability;
   346→  }
   347→  
   348→  /**
   349→   * Choose random element from array
   350→   */
   351→  choose<T>(array: T[]): T {
   352→    return array[Math.floor(this.next() * array.length)];
   353→  }
   354→}
