   597→  /**
   598→   * Create a deep snapshot of game state, preserving Map and Set objects
   599→   * Uses structuredClone (modern API) which handles complex objects correctly
   600→   */
   601→  private snapshotState(state: GameState): GameState {
   602→    try {
   603→      // structuredClone is available in Node 17+ and modern browsers
   604→      // It correctly handles Map, Set, Date, RegExp, etc.
   605→      const cloned = structuredClone(state);
   606→
   607→      // FIX #14 (Oct 2025): techTreeState is now a required property, no debug needed
   608→      // structuredClone properly deep-clones all GameState properties including techTreeState
   609→
   610→      return cloned;
   611→    } catch (error) {
   612→      // Fallback for older Node versions: manual reconstruction
   613→      console.warn('structuredClone not available, using manual snapshot');
   614→
   615→      // Create shallow copy
   616→      const snapshot = { ...state };
   617→
   618→      // Deep clone arrays
   619→      snapshot.aiAgents = state.aiAgents.map(ai => ({ ...ai }));
   620→      snapshot.organizations = state.organizations.map(org => ({ ...org }));
   621→      snapshot.eventLog = [...state.eventLog];
   622→
   623→      // Preserve Map objects
   624→      if (state.computeInfrastructure?.computeAllocations) {
   625→        snapshot.computeInfrastructure = {
   626→          ...state.computeInfrastructure,
   627→          computeAllocations: new Map(state.computeInfrastructure.computeAllocations)
   628→        };
   629→      }
   630→
   631→      // Preserve Set objects
   632→      if (state.radiationSystem?.contaminatedRegions) {
   633→        snapshot.radiationSystem = {
   634→          ...state.radiationSystem,
   635→          contaminatedRegions: new Set(state.radiationSystem.contaminatedRegions)
   636→        };
   637→      }
   638→
   639→      if (state.biodiversitySystem?.regions) {
   640→        snapshot.biodiversitySystem = {
   641→          ...state.biodiversitySystem,
   642→          regions: new Map(state.biodiversitySystem.regions),
   643→          regionalWeights: new Map(state.biodiversitySystem.regionalWeights)
   644→        };
   645→      }
   646→
   647→      return snapshot;
   648→    }
   649→  }
