   651→  /**
   652→   * Run simulation until a stop condition is met
   653→   */
   654→  run(initialState: GameState, stopConditions?: {
   655→    maxMonths?: number;
   656→    checkActualOutcomes?: boolean; // Stop when ACTUAL outcomes occur (not probabilities)
   657→    onMonthEnd?: (state: GameState) => void; // Callback after each month
   658→    logLevel?: LogLevel; // Override log level for this run
   659→    seed?: number; // Override seed for this run
   660→    snapshotInterval?: number; // Override snapshot interval for this run
   661→    stopOnOutcome?: boolean; // Stop simulation when final outcome reached
   662→    outcomeThreshold?: number; // Threshold for outcome probability
   663→  }): SimulationRunResult {
   664→    const maxMonths = stopConditions?.maxMonths ?? this.config.maxMonths!;
   665→    const checkActualOutcomes = stopConditions?.checkActualOutcomes ?? true;
   666→    const logLevel = this.config.logLevel ?? 'quartile';
   667→
   668→    // Phase 1B (Oct 17, 2025): Capture initial population BEFORE any mutations
   669→    // This is critical because state = initialState (same reference), so mutations affect both
   670→    const savedInitialPopulation = initialState.humanPopulationSystem.population;
   671→
   672→    // Reset crisis points for this run
   673→    const { resetCrisisPoints } = require('./crisisPoints');
   674→    resetCrisisPoints();
   675→
   676→    // Initialize logger with estimated duration
   677→    const logger = new SimulationLogger(this.config.seed!, logLevel, maxMonths);
   678→    const diagnosticLogger = new DiagnosticLogger();
   679→    const eventAggregator = new EventAggregator(12); // Report every 12 months
   680→
   681→    let state = initialState;
   682→    const history: SimulationStepResult[] = [];
   683→    let actualOutcome: OutcomeType | null = null;
   684→    let actualOutcomeReason: string = '';
   685→    
   686→    // Phase 3: Initialize end-game state if not present
   687→    if (!state.endGameState) {
   688→      state.endGameState = initializeEndGameState();
   689→    }
   690→    
   691→    // BUG FIX (Oct 16, 2025): Attach EventAggregator before loop starts
   692→    // Ensures it's always available even if simulation breaks early
   693→    (state as any).eventAggregator = eventAggregator;
   694→    
   695→    const snapshotInterval = this.config.snapshotInterval ?? 12; // Default: snapshot every 12 months
   696→    // NOTE: For very long simulations (1000+ months), history array can consume gigabytes.
   697→    // Consider reducing snapshot frequency or implementing max history size (BUG-14, Oct 16 2025)
   698→    // Current: 12-month interval = ~100 snapshots per 1200 months (~1-2GB RAM)
   699→
   700→    for (let month = 0; month < maxMonths; month++) {
   701→      const stepResult = this.step(state);
   702→
   703→      // Snapshot state at configured intervals to preserve history
   704→      // This is expensive, so we do it sparingly (default: every 12 months)
   705→      if (month % snapshotInterval === 0 || month === maxMonths - 1) {
   706→        history.push({
   707→          ...stepResult,
   708→          state: this.snapshotState(state)
