     1→/**
     2→ * Mortality and Famine Risk Calculations
     3→ *
     4→ * This module handles environmental mortality calculations and famine risk detection.
     5→ * These functions were extracted from the original qualityOfLife.ts during refactoring.
     6→ *
     7→ * Research basis:
     8→ * - UNEP (2024): Planetary boundaries and mortality impacts
     9→ * - IPBES (2019): Ecosystem collapse → agricultural failure → famine
    10→ * - FAO State of Food Security (2024): Famine triggers and thresholds
    11→ */
    12→
    13→import { GameState } from '@/types/game';
    14→
    15→/**
    16→ * Environmental mortality breakdown by cause
    17→ */
    18→export interface EnvironmentalMortalityBreakdown {
    19→  total: number;           // Total monthly mortality rate
    20→  famine: number;          // Deaths from food insecurity
    21→  disease: number;         // Deaths from water/sanitation
    22→  climate: number;         // Deaths from heat/disasters
    23→  ecosystem: number;       // Deaths from biodiversity loss
    24→  pollution: number;       // Deaths from pollution (baseline)
    25→}
    26→
    27→/**
    28→ * Calculate environmental mortality rate based on threshold crossings
    29→ *
    30→ * Research-based (UNEP 2024, PNAS 2014):
    31→ * - Current (2025): 7/9 boundaries, 9M deaths/8B people = 0.009% monthly
    32→ * - Mortality scales with food, water, climate, biodiversity thresholds
    33→ * - Non-linear escalation when multiple systems fail
    34→ *
    35→ * FIX (Oct 13, 2025): Now returns breakdown by cause to properly track deaths
    36→ * P0.6 (Oct 15, 2025): Episodic environmental shocks instead of continuous noise
    37→ * Research: Real environmental disasters are episodic (heatwaves, droughts, famines)
    38→ *   - Events occur with ~5% monthly probability based on environmental stress
    39→ *   - Events cause 50-200% mortality spikes for 3-12 months
    40→ *   - Between events: minimal variation (baseline + small noise)
    41→ * Returns monthly mortality rate (0-1, where 0.01 = 1% die per month)
    42→ */
    43→export function calculateEnvironmentalMortality(state: GameState, month: number): EnvironmentalMortalityBreakdown {
    44→  const env = state.environmentalAccumulation;
    45→  const boundaries = state.planetaryBoundariesSystem;
    46→  if (!env || !boundaries) {
    47→    return { total: 0, famine: 0, disease: 0, climate: 0, ecosystem: 0, pollution: 0 };
    48→  }
    49→
    50→  let famineMortality = 0;
    51→  let diseaseMortality = 0;
    52→  let climateMortality = 0;
    53→  let ecosystemMortality = 0;
    54→  let pollutionMortality = 0;
    55→
    56→  // === BASELINE (Current 2025 conditions) ===
    57→  // 7/9 boundaries breached = 0.009% monthly (UNEP: 9M deaths/year globally)
    58→  // Pollution is the main driver of current baseline mortality
    59→  if (boundaries.boundariesBreached >= 7) {
    60→    pollutionMortality = 0.00009; // 0.009% baseline
    61→  }
    62→
    63→  // === FOOD SECURITY (Highest immediate impact) ===
    64→  // Food < 0.4 = crisis, Food < 0.2 = catastrophic
    65→  // FIX (Oct 13, 2025): foodSecurity is in survivalFundamentals, not environmentalAccumulation
    66→  const foodSecurity = state.qualityOfLifeSystems?.survivalFundamentals?.foodSecurity ?? 0.7;
    67→  if (foodSecurity < 0.4) {
    68→    const foodSeverity = (0.4 - foodSecurity) / 0.4; // 0-1 scale
    69→    famineMortality += 0.0001 * Math.pow(foodSeverity, 1.5); // 0.01%/month at threshold, scales up
    70→
    71→    if (foodSecurity < 0.2) {
    72→      // Catastrophic food crisis: additional mortality
    73→      const catSeverity = (0.2 - foodSecurity) / 0.2;
    74→      famineMortality += 0.0005 * catSeverity; // Up to 0.05%/month additional
    75→    }
    76→  }
    77→
    78→  // === WATER SECURITY ===
    79→  // Water < 0.4 = crisis (leads to cholera, dysentery, other waterborne disease)
    80→  // Note: waterSecurity not in EnvironmentalAccumulation, use QoL system
    81→  const waterSecurity = state.qualityOfLifeSystems.survivalFundamentals?.waterSecurity || 0.7;
    82→  if (waterSecurity < 0.4) {
    83→    const waterSeverity = (0.4 - waterSecurity) / 0.4;
    84→    diseaseMortality += 0.00008 * Math.pow(waterSeverity, 1.5); // Slightly less immediate than food
    85→  }
    86→
    87→  // === CLIMATE STABILITY (Heat stress, disasters) ===
    88→  // Climate < 0.5 = severe, Climate < 0.3 = catastrophic
    89→  const climateStability = env.climateStability || 0.75;
    90→  if (climateStability < 0.6) {
    91→    const climateSeverity = (0.6 - climateStability) / 0.6;
    92→    climateMortality += 0.00005 * Math.pow(climateSeverity, 2); // Non-linear escalation
    93→  }
    94→
    95→  // === BIODIVERSITY LOSS (Ecosystem services collapse) ===
    96→  // Biodiversity < 0.3 = critical, < 0.2 = collapse
    97→  // Loss of pollination, disease regulation, etc.
    98→  const biodiversity = env.biodiversityIndex || 0.35;
    99→  if (biodiversity < 0.3) {
   100→    const bioSeverity = (0.3 - biodiversity) / 0.3;
   101→    ecosystemMortality += 0.00003 * Math.pow(bioSeverity, 1.5); // Pollination, disease regulation lost
