/**
 * Quality of Life Phase
 *
 * Updates multi-dimensional quality of life systems and calculates aggregate QoL
 * Order: 34.0 (after social stability)
 */

import { GameState, SimulationPhase, PhaseResult, PhaseContext, RNGFunction } from '@/types/game';
import { updateQualityOfLifeSystems, calculateQualityOfLife } from '../../calculations';

export class QualityOfLifePhase implements SimulationPhase {
  readonly id = 'quality-of-life';
  readonly name = 'Quality of Life Systems';
  readonly order = 34.0;

  execute(state: GameState, rng: RNGFunction): PhaseResult {
    // Update multi-dimensional quality of life systems
    const updatedQoLSystems = updateQualityOfLifeSystems(state);
    state.qualityOfLifeSystems = updatedQoLSystems;

    // Calculate aggregate quality of life from systems
    const qualityOfLife = calculateQualityOfLife(updatedQoLSystems);
    state.globalMetrics = {
      ...state.globalMetrics,
      qualityOfLife
    };

    return { events: [] };
  }
}

/**
 * Food Security Degradation Phase
 *
 * Phase 1B Refinement (Oct 17, 2025): Apply monthly food security degradation during crises
 *
 * Degradation applies when environmental/resource crises are active, NOT just during cascades.
 * This ensures famines can trigger even if planetary boundary cascades haven't started yet.
 *
 * Research basis:
 * - Historical food crises show 5-15% monthly decline in food availability
 * - Multiple simultaneous crises have compounding effects
 * - Infrastructure breakdown accelerates food system collapse
 *
 * Order: 34.5 (AFTER QualityOfLifePhase at 34.0, which calculates initial food security)
 * CRITICAL: Must run AFTER QualityOfLifePhase, otherwise degradation gets overwritten!
 */

import { GameState, SimulationPhase, PhaseResult, PhaseContext, RNGFunction } from '@/types/game';

