     3→ *
     4→ * Orchestrates all QoL subsystems:
     5→ * - Survival fundamentals (food, water, shelter, habitability)
     6→ * - Basic needs (material, energy, safety)
     7→ * - Psychological needs (mental health, meaning, connection, autonomy)
     8→ * - Social needs (freedom, information, community, culture)
     9→ * - Health (healthcare, longevity, disease burden)
    10→ * - Environmental (ecosystem, climate, pollution)
    11→ * - Distribution metrics (regional inequality)
    12→ *
    13→ * Performance optimizations:
    14→ * - Regional cache to eliminate O(n) array scans
    15→ * - Pre-computed dimension weights
    16→ * - Modular structure for easier optimization
    17→ */
    18→
    19→import type { GameState, QualityOfLifeSystems } from '@/types/game';
    20→import { getTrustInAI } from '../socialCohesion';
    21→import { calculateSurvivalFundamentals } from './dimensions';
    22→import {
    23→  calculateUnemploymentPenalty,
    24→  calculateFoodSecurityPenalty,
    25→  calculatePopulationCollapsePenalty,
    26→  calculateTraumaPenalty,
    27→  calculateTraumaInstitutionalErosion,
    28→  calculateUBIFloor,
    29→  calculateUBIMentalHealthBonus,
    30→  calculateUBIShelterFloor,
    31→  calculatePostScarcityMultipliers,
    32→} from './penalties';
    33→import { calculateDistributionMetrics, calculateRegionalInequality } from './regional';
    34→import type { RegionalCache } from './cache/regionalCache';
    35→
    36→/**
    37→ * Update all quality of life dimensions based on current game state
    38→ *
    39→ * This function calculates how each QoL dimension changes based on:
    40→ * - Economic conditions (unemployment, stage, wealth)
    41→ * - AI impacts (beneficial/harmful actions, capability)
    42→ * - Government policies (legitimacy, control, regulations)
    43→ * - Social dynamics (adaptation, trust, stability)
    44→ *
    45→ * Returns updated QoL systems that can then be aggregated via calculateQualityOfLife()
    46→ *
    47→ * Performance note: This function is called every simulation step, so optimizations matter.
    48→ * Regional cache is passed in to enable memoization across multiple calls in same month.
    49→ */
    50→export function updateQualityOfLifeSystems(
    51→  state: GameState,
    52→  regionalCache: RegionalCache | null = null
    53→): QualityOfLifeSystems {
    54→  const { globalMetrics, society, aiAgents, government, qualityOfLifeSystems: current } = state;
    55→
    56→  const totalAICapability = aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
    57→  const avgAlignment = aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, aiAgents.length);
    58→  const beneficialActions = aiAgents.reduce((sum, ai) => sum + ai.beneficialActions, 0);
    59→  const harmfulActions = aiAgents.reduce((sum, ai) => sum + ai.harmfulActions, 0);
    60→  const economicStage = globalMetrics.economicTransitionStage;
    61→
    62→  // Detect NaN in key inputs - fail loudly
    63→  if (isNaN(totalAICapability)) {
    64→    console.error(`❌ NaN totalAICapability in updateQualityOfLifeSystems at month ${state.currentMonth}`);
    65→    console.error(`   AI agents: ${aiAgents.map(ai => `${ai.id}: ${ai.capability}`).join(', ')}`);
    66→    throw new Error(`NaN in totalAICapability - check AI agent capabilities`);
    67→  }
    68→
    69→  if (isNaN(economicStage)) {
    70→    console.error(`❌ NaN economicStage in updateQualityOfLifeSystems at month ${state.currentMonth}`);
    71→    console.error(`   economicTransitionStage: ${globalMetrics.economicTransitionStage}`);
    72→    throw new Error(`NaN in economicStage - check globalMetrics.economicTransitionStage`);
    73→  }
    74→
    75→  // Phase 1.2: Check for UBI (strengthens safety net effects)
    76→  const hasUBI = government.activeRegulations.some(reg => reg.includes('UBI'));
    77→  const ubiVariant = government.structuralChoices.ubiVariant || 'none';
    78→  const hasGenerousUBI = ubiVariant === 'generous';
    79→
    80→  // === BASIC NEEDS ===
    81→
    82→  // Material abundance: AI capability helps, unemployment hurts, stage matters
    83→  const aiProductionBonus = totalAICapability * avgAlignment * 0.1;
    84→  const unemploymentPenalty = calculateUnemploymentPenalty(society.unemploymentLevel, economicStage);
    85→  const wealthBonus = globalMetrics.wealthDistribution * 0.3;
    86→  let materialAbundance = 0.8 + aiProductionBonus + unemploymentPenalty + wealthBonus;
    87→
    88→  // UBI floor
    89→  if (hasUBI) {
    90→    const ubiFloor = calculateUBIFloor(economicStage, hasGenerousUBI);
    91→    materialAbundance = Math.max(materialAbundance, ubiFloor);
    92→  }
    93→
    94→  // Food security penalty
    95→  const foodSecurity = state.qualityOfLifeSystems?.survivalFundamentals?.foodSecurity ?? 0.7;
    96→  if (foodSecurity < 0.7) {
    97→    const foodPenalty = calculateFoodSecurityPenalty(foodSecurity);
    98→    materialAbundance -= foodPenalty;
    99→  }
   100→
   101→  // Post-scarcity multipliers
   102→  const pop = state.humanPopulationSystem;
   103→  const populationFraction = pop.baselinePopulation > 0
   104→    ? pop.population / pop.baselinePopulation
   105→    : 1.0; // Fallback to 1.0 if baseline is invalid
   106→
   107→  if (economicStage >= 4) {
   108→    const { materialBonus, infrastructureScaling } = calculatePostScarcityMultipliers(
   109→      economicStage,
   110→      totalAICapability,
   111→      populationFraction
   112→    );
   113→    materialAbundance += materialBonus;
   114→    materialAbundance = Math.min(3.0, Math.max(0, materialAbundance));
   115→  } else {
   116→    materialAbundance = Math.max(0, Math.min(2, materialAbundance));
   117→  }
   118→
   119→  // Population collapse penalty (all stages)
   120→  if (populationFraction < 0.5) {
   121→    const collapseMultiplier = calculatePopulationCollapsePenalty(pop.population, pop.baselinePopulation);
   122→    materialAbundance *= collapseMultiplier;
   123→  }
   124→
   125→  // Energy availability
   126→  let energyAvailability = 0.9 + totalAICapability * 0.05 + economicStage * 0.1;
   127→
   128→  // Detect NaN after initial calculation
   129→  if (isNaN(energyAvailability)) {
   130→    console.error(`❌ NaN energyAvailability after initial calculation at month ${state.currentMonth}`);
   131→    console.error(`   totalAICapability: ${totalAICapability}`);
   132→    console.error(`   economicStage: ${economicStage}`);
   133→    console.error(`   calculation: 0.9 + ${totalAICapability} * 0.05 + ${economicStage} * 0.1 = ${energyAvailability}`);
   134→    throw new Error(`NaN in energyAvailability calculation`);
   135→  }
   136→
   137→  if (economicStage >= 4) {
   138→    const { energyBonus, infrastructureScaling } = calculatePostScarcityMultipliers(
   139→      economicStage,
   140→      totalAICapability,
   141→      populationFraction
   142→    );
   143→    energyAvailability += energyBonus;
   144→    energyAvailability = Math.min(3.0, Math.max(0, energyAvailability));
   145→  } else {
   146→    energyAvailability = Math.max(0, Math.min(2, energyAvailability));
   147→  }
   148→
   149→  // Energy grid collapse penalty
   150→  if (populationFraction < 0.5) {
   151→    const gridCollapseMultiplier = populationFraction < 0.1
   152→      ? 0.15
   153→      : 0.15 + (populationFraction * 0.85);
   154→    energyAvailability *= gridCollapseMultiplier;
   155→  }
   156→
   157→  // Physical safety
   158→  let physicalSafety = globalMetrics.socialStability * 0.8 + government.legitimacy * 0.2;
   159→  physicalSafety -= harmfulActions * 0.05;
   160→
   161→  if (economicStage >= 4 && materialAbundance > 1.5) {
   162→    physicalSafety += 0.2; // Less crime when everyone has enough
   163→  }
   164→
   165→  physicalSafety = Math.max(0, Math.min(1, physicalSafety));
   166→
   167→  // === PSYCHOLOGICAL NEEDS ===
   168→
   169→  // Mental health
   170→  let mentalHealth = 0.6;
   171→  mentalHealth += globalMetrics.socialStability * 0.3;
   172→  mentalHealth -= society.unemploymentLevel * (economicStage < 3 ? 0.4 : -0.2);
   173→  mentalHealth += current.meaningAndPurpose * 0.2;
   174→
   175→  if (hasUBI) {
   176→    const ubiMentalBonus = calculateUBIMentalHealthBonus(economicStage, hasGenerousUBI);
   177→    mentalHealth += ubiMentalBonus;
   178→  }
   179→
   180→  if (economicStage >= 4 && materialAbundance > 1.5) {
   181→    mentalHealth += 0.15;
   182→  }
   183→
   184→  mentalHealth = Math.max(0, Math.min(1, mentalHealth));
   185→
   186→  // Meaning and purpose
   187→  let meaningAndPurpose = 0.65;
   188→  if (economicStage >= 3 && society.unemploymentLevel > 0.6) {
   189→    meaningAndPurpose = 0.4 + (economicStage - 3) * 0.2;
   190→  } else if (economicStage >= 4) {
   191→    meaningAndPurpose = 0.8 + totalAICapability * 0.05;
   192→  }
   193→  meaningAndPurpose = Math.max(0, Math.min(1, meaningAndPurpose));
   194→
   195→  // Social connection
   196→  let socialConnection = 0.55 + current.communityStrength * 0.3;
   197→  if (globalMetrics.socialStability < 0.4) {
   198→    socialConnection += 0.2;
   199→  } else if (materialAbundance > 1.5) {
   200→    socialConnection -= 0.1;
   201→  }
   202→  socialConnection = Math.max(0, Math.min(1, socialConnection));
   203→
   204→  // Autonomy
   205→  let autonomy = 0.7;
   206→  autonomy -= government.controlDesire * 0.3;
   207→  autonomy -= government.structuralChoices.surveillanceLevel * 0.4;
   208→  if (government.structuralChoices.surveillanceLevel > 0.7) {
   209→    autonomy -= 0.3;
   210→  }
   211→  autonomy += current.politicalFreedom * 0.2;
   212→
   213→  // Autonomy floor
   214→  const govQuality = government.governanceQuality;
   215→  const democraticFloor = government.governmentType === 'democratic' ? 0.25 :
   216→                          government.governmentType === 'technocratic' ? 0.15 : 0.05;
   217→  const transparencyFloor = (govQuality?.transparency || 0.5) * 0.15;
   218→  const participationFloor = (govQuality?.participationRate || 0.5) * 0.10;
   219→
   220→  // Tech tree: collective purpose networks provide autonomy boost
   221→  const counterSurveillanceTech = require('../techTree/helpers').isTechDeployed(state, 'collective_purpose_networks') * 0.25; // Combined boost
   222→
   223→  const minimumAutonomy = democraticFloor + transparencyFloor + participationFloor + counterSurveillanceTech;
   224→  autonomy = Math.max(minimumAutonomy, Math.min(1, autonomy));
   225→
   226→  // === SOCIAL NEEDS ===
   227→
   228→  // Political freedom
   229→  let politicalFreedom = government.legitimacy * 0.7 + (1 - government.controlDesire) * 0.3;
   230→  if (government.governmentType === 'authoritarian') {
   231→    politicalFreedom *= 0.5;
   232→  } else if (government.governmentType === 'democratic') {
   233→    politicalFreedom *= 1.1;
   234→  }
   235→  if (government.structuralChoices.surveillanceLevel > 0.7) {
   236→    politicalFreedom -= 0.3;
   237→  }
   238→  if (globalMetrics.socialStability < 0.3) {
   239→    politicalFreedom *= 0.8;
   240→  }
   241→  politicalFreedom = Math.max(0, Math.min(1, politicalFreedom));
   242→
   243→  // Information integrity
   244→  const trustInAI = getTrustInAI(society);
   245→  let informationIntegrity = 0.5 + trustInAI * 0.3;
   246→  informationIntegrity -= (totalAICapability * (1 - avgAlignment)) * 0.2;
   247→  informationIntegrity = Math.max(0, Math.min(1, informationIntegrity));
   248→
   249→  // Community strength
   250→  let communityStrength = 0.5 + society.socialAdaptation * 0.3 + globalMetrics.socialStability * 0.2;
   251→
   252→  // Tech tree: collective purpose networks boost community
   253→  const communityTechBoost = require('../techTree/helpers').isTechDeployed(state, 'collective_purpose_networks') * 0.15;
   254→  const postScarcityBoost = economicStage >= 3 ? 0.10 : 0;
   255→  const ubiBoost = hasUBI ? 0.05 : 0;
   256→
   257→  communityStrength += communityTechBoost + postScarcityBoost + ubiBoost;
   258→  communityStrength = Math.max(0, Math.min(1, communityStrength));
   259→
   260→  // Cultural vitality
   261→  let culturalVitality = 0.7 + politicalFreedom * 0.2;
   262→  if (totalAICapability > 1.0 && avgAlignment > 0.7) {
   263→    culturalVitality += 0.1;
   264→  }
   265→  culturalVitality = Math.max(0, Math.min(1, culturalVitality));
   266→
   267→  // === HEALTH AND LONGEVITY ===
   268→
   269→  let healthcareQuality = 0.75 + totalAICapability * avgAlignment * 0.15;
   270→  healthcareQuality = Math.max(0, Math.min(1, healthcareQuality));
   271→
   272→  let longevityGains = 0.1 + totalAICapability * avgAlignment * 0.1;
   273→  longevityGains = Math.max(0, Math.min(2, longevityGains));
   274→
   275→  let diseasesBurden = 0.3 - totalAICapability * avgAlignment * 0.1;
   276→  diseasesBurden += harmfulActions * 0.02;
   277→  diseasesBurden = Math.max(0, Math.min(1, diseasesBurden));
   278→
   279→  // === ENVIRONMENTAL ===
   280→
   281→  let ecosystemHealth = 0.4;
   282→  if (totalAICapability > 1.5 && avgAlignment > 0.7) {
   283→    ecosystemHealth += (totalAICapability - 1.5) * 0.2;
   284→  } else if (totalAICapability > 2.0 && avgAlignment < 0.5) {
   285→    ecosystemHealth -= 0.2;
   286→  }
   287→  ecosystemHealth = Math.max(0, Math.min(1, ecosystemHealth));
   288→
   289→  let climateStability = current.climateStability - 0.002;
   290→  if (totalAICapability > 1.5 && avgAlignment > 0.7) {
   291→    climateStability += 0.01;
   292→  }
   293→  climateStability = Math.max(0, Math.min(1, climateStability));
   294→
   295→  let pollutionLevel = 0.5 + economicStage * 0.05 - totalAICapability * avgAlignment * 0.1;
   296→  pollutionLevel = Math.max(0, Math.min(1, pollutionLevel));
   297→
   298→  // === BREAKTHROUGH TECHNOLOGY BOOSTS ===
   299→  // NOTE: Technology effects now applied via TechTreePhase regional deployment
   300→  // QoL boosts are calculated directly from state.techTreeState.technologies
   301→  // No additional boosts needed here - tech tree handles all effects
   302→
   303→  // === PSYCHOLOGICAL TRAUMA EFFECTS ===
   304→  if (state.psychologicalTrauma && state.psychologicalTrauma.traumaLevel > 0) {
   305→    const traumaPenalties = calculateTraumaPenalty(state.psychologicalTrauma.traumaLevel);
   306→
   307→    mentalHealth *= (1 - traumaPenalties.mentalHealthPenalty);
   308→    socialConnection *= (1 - traumaPenalties.socialConnectionPenalty);
   309→    communityStrength *= (1 - traumaPenalties.communityStrengthPenalty);
   310→
   311→    if (traumaPenalties.mentalHealthPenalty > 0.25) {
   312→      console.log(`\n  💔 Psychological trauma impact: -${(traumaPenalties.mentalHealthPenalty * 100).toFixed(0)}% mental health, -${(traumaPenalties.socialConnectionPenalty * 100).toFixed(0)}% social connection`);
   313→    }
   314→  }
   315→
   316→  // === INSTITUTIONAL TRUST EROSION FROM TRAUMA ===
   317→  if (state.psychologicalTrauma && state.psychologicalTrauma.traumaLevel > 0.3) {
   318→    const traumaErosion = calculateTraumaInstitutionalErosion(state.psychologicalTrauma.traumaLevel);
   319→
   320→    if (state.government && state.government.legitimacy !== undefined) {
   321→      state.government.legitimacy *= (1 - traumaErosion);
   322→    }
   323→
   324→    if (state.socialAccumulation && state.socialAccumulation.socialCohesion !== undefined) {
   325→      // Trauma erodes all social cohesion components
   326→      const erosionFactor = 1 - traumaErosion * 0.5;
   327→      state.socialAccumulation.socialCohesion.trust *= erosionFactor;
   328→      state.socialAccumulation.socialCohesion.communityBonds *= erosionFactor;
   329→      state.socialAccumulation.socialCohesion.civilLiberties *= erosionFactor;
   330→    }
   331→  }
   332→
   333→  // === SURVIVAL FUNDAMENTALS ===
   334→  // FIX (Oct 25, 2025): Preserve foodSecurity from FoodSecurityDegradationPhase
   335→  // FoodSecurityDegradationPhase applies BOTH crisis degradation AND infrastructure penalty
   336→  // Preserving allows degradation to accumulate month-over-month correctly
   337→  const survivalFundamentals = state.qualityOfLifeSystems.survivalFundamentals
   338→    ? {
   339→        // Preserve foodSecurity from FoodSecurityDegradationPhase (includes infrastructure penalty)
   340→        foodSecurity: state.qualityOfLifeSystems.survivalFundamentals.foodSecurity,
   341→        // Recalculate other survival fundamentals
   342→        ...(() => {
   343→          const calculated = calculateSurvivalFundamentals(state);
   344→          return {
   345→            waterSecurity: calculated.waterSecurity,
   346→            thermalHabitability: calculated.thermalHabitability,
   347→            shelterSecurity: calculated.shelterSecurity,
   348→          };
   349→        })()
   350→      }
   351→    : calculateSurvivalFundamentals(state); // First time initialization
   352→
   353→  // Assign to state
   354→  state.qualityOfLifeSystems.survivalFundamentals = survivalFundamentals;
   355→
   356→  // === DISTRIBUTION METRICS ===
   357→  const distribution = calculateDistributionMetrics(
   358→    state,
   359→    survivalFundamentals,
   360→    {
   361→      materialAbundance,
   362→      energyAvailability,
   363→      physicalSafety,
   364→      mentalHealth,
   365→      healthcareQuality
   366→    },
   367→    regionalCache
   368→  );
   369→
   370→  // === REGIONAL INEQUALITY (DEPRECATED - backward compatibility) ===
   371→  const regionalInequality = calculateRegionalInequality(state, {
   372→    materialAbundance,
   373→    energyAvailability,
   374→    physicalSafety,
   375→    mentalHealth,
   376→    healthcareQuality
   377→  });
   378→
   379→  // === HEALTH AGGREGATE ===
   380→  // Calculate aggregate health metric from health tier components
   381→  // Matches aggregation.ts formula: (healthcareQuality * 0.4 + longevityGains * 0.3 + (1 - diseasesBurden) * 0.3)
   382→  const health = (
   383→    healthcareQuality * 0.4 +
   384→    longevityGains * 0.3 +
   385→    (1 - diseasesBurden) * 0.3
   386→  );
   387→
   388→  return {
   389→    // Survival fundamentals (required)
   390→    survivalFundamentals,
   391→
   392→    // Basic needs
   393→    materialAbundance,
   394→    energyAvailability,
   395→    physicalSafety,
   396→
   397→    // Psychological
   398→    mentalHealth,
   399→    meaningAndPurpose,
   400→    socialConnection,
   401→    autonomy,
   402→
   403→    // Social
   404→    politicalFreedom,
   405→    informationIntegrity,
   406→    communityStrength,
   407→    culturalVitality,
   408→
   409→    // Health
   410→    healthcareQuality,
   411→    longevityGains,
   412→    diseasesBurden,
   413→    health, // Aggregate health metric (required)
   414→
   415→    // Environmental
   416→    ecosystemHealth,
   417→    climateStability,
   418→    pollutionLevel,
   419→
   420→    // Distribution metrics (required)
   421→    distribution,
   422→
   423→    // DEPRECATED (backward compatibility)
   424→    regionalInequality
   425→  };
   426→}
   427→
   428→/**
   429→ * Initialize quality of life systems with baseline values
   430→ * Represents early 2025 starting conditions
   431→ */
   432→export function initializeQualityOfLifeSystems(): QualityOfLifeSystems {
   433→  return {
   434→    // NEW: Survival Fundamentals (Oct 12, 2025)
   435→    // Baseline 2025: Most people have food/water/shelter, but stressed
   436→    survivalFundamentals: {
   437→      foodSecurity: 0.85,           // 85% food secure (FAO: ~10% undernourished globally)
   438→      waterSecurity: 0.80,           // 80% water secure (WHO: ~25% lack safely managed water)
   439→      thermalHabitability: 1.0,      // 100% habitable (at current +1.1°C)
   440→      shelterSecurity: 0.75,         // 75% adequate housing (UN: ~1.6B inadequate housing)
   441→    },
   442→
   443→    // Basic Needs - moderate in developed world
   444→    materialAbundance: 0.8,
   445→    energyAvailability: 0.9,
   446→    physicalSafety: 0.85,
   447→
   448→    // Psychological - struggling but functional
   449→    mentalHealth: 0.6,
   450→    meaningAndPurpose: 0.65,
   451→    socialConnection: 0.55,
   452→    autonomy: 0.7,
   453→
   454→    // Social - mixed democratic health
   455→    politicalFreedom: 0.7,
   456→    informationIntegrity: 0.5, // Low due to social media
   457→    communityStrength: 0.5,
   458→    culturalVitality: 0.7,
   459→
   460→    // Health - good but room for improvement
   461→    healthcareQuality: 0.75,
   462→    longevityGains: 0.1, // Slight gains above historical baseline
   463→    diseasesBurden: 0.3,
   464→    // FIX (Oct 26, 2025): Initialize health property (required by novelEntities.ts)
   465→    // Aggregate of health tier: baseline 0.7 (good healthcare, moderate disease burden)
   466→    health: 0.7,
   467→
   468→    // Environmental - declining
   469→    ecosystemHealth: 0.4,
   470→    climateStability: 0.6,
   471→    pollutionLevel: 0.5,
   472→
   473→    // NEW: Distribution Metrics (Oct 12, 2025)
   474→    // Baseline 2025: Moderate inequality, some regional crises
   475→    distribution: {
   476→      globalGini: 0.38,              // Current global Gini ~0.38 (World Bank)
   477→      regionalVariance: 0.08,        // Moderate variance
   478→      crisisAffectedFraction: 0.15,  // ~15% in acute crisis zones (conflicts, droughts)
   479→      worstRegionQoL: 0.35,          // Worst regions (conflict zones, extreme poverty)
   480→      bestRegionQoL: 0.95,           // Best regions (Nordic countries, high HDI)
   481→      medianRegionQoL: 0.65,         // Median region
   482→      isDystopicInequality: false,   // Not yet dystopian
   483→      isRegionalDystopia: false,     // Not yet regional dystopia
   484→    }
   485→  };
   486→}
