  const tempAnomaly = resources.co2.temperatureAnomaly;
  if (tempAnomaly > 1.5) {
    const baseClimateImpact = (tempAnomaly - 1.5) * 0.15;
    const climatePenalty = baseClimateImpact * (0.5 + region.climateVulnerability * 0.5);
    foodSecurity -= climatePenalty;
  }

