  if (state.biodiversitySystem) {
    const globalBio = state.biodiversitySystem.globalBiodiversityIndex;
    const vulnerabilityMultiplier = 0.7 + region.climateVulnerability * 0.3;

    if (globalBio < 0.80) {
      const pollinatorLoss = 0.80 - globalBio;
      const pollinationPenalty = pollinatorLoss * 0.35 * vulnerabilityMultiplier;
      foodSecurity -= pollinationPenalty;
    }

    if (globalBio < 0.60) {
      const soilHealthLoss = 0.60 - globalBio;
      const soilPenalty = soilHealthLoss * 0.25 * vulnerabilityMultiplier;
      foodSecurity -= soilPenalty;
    }

    if (globalBio < 0.50) {
      const pestControlLoss = 0.50 - globalBio;
      const pestPenalty = pestControlLoss * 0.20 * vulnerabilityMultiplier;
      foodSecurity -= pestPenalty;
    }
  }

  // AI enhancement (global technology, available to all regions)
  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  if (totalAI > 1.5 && avgAlignment > 0.7) {
    const aiAgriculture = Math.min(0.3, (totalAI - 1.5) * 0.1);
    foodSecurity += aiAgriculture;
  }

  // Breakthrough technologies (global deployment, available to all regions)
  const getTech = require('../techTree/helpers').isTechDeployed;
  const verticalFarming = getTech(state, 'vertical_farming');
  foodSecurity += verticalFarming * 0.25;

  const circularFood = getTech(state, 'circular_food_systems');
  foodSecurity += circularFood * 0.15;

  // Legacy support
  const sustainableAg = getTech(state, 'sustainableAgriculture');
  if (sustainableAg > 0 && verticalFarming === 0) {
    foodSecurity += sustainableAg * 0.3;
  }

  return Math.max(0, Math.min(1.5, foodSecurity));
}

