```typescript
/**
 * Calculate REGIONAL food security (Oct 25, 2025)
 *
 * Food insecurity in one region doesn't always fully propagate to others.
 * Regions vary by:
 * - Local production vs import dependency
 * - Infrastructure relative to regional baseline
 * - Exposure to climate/water/biodiversity crises
 */
export function calculateRegionalFoodSecurity(
  state: GameState,
  region: { name: string; population: number; climateVulnerability: number; resourceVulnerability: number }
): number {
  const resources = state.resourceEconomy;
  const phosphorus = state.phosphorusSystem;
  const ocean = state.oceanAcidificationSystem;
  const freshwater = state.freshwaterSystem;

  // Base food availability from GLOBAL resource stocks
  let foodSecurity = Math.min(1.0, resources.food.reserves);

  // REGIONAL infrastructure penalty (BUGGY - see Current Work section)
  const regionalBaseline = region.population;
  const regionalPopulationRatio = region.population / regionalBaseline;
  const infrastructurePenalty = Math.min(1.0, Math.max(0.3, regionalPopulationRatio));
  foodSecurity *= infrastructurePenalty;

  // Phosphorus price crisis (import-dependent regions hit harder)
  if (phosphorus && phosphorus.priceIndex > 2.0) {
    const basePriceImpact = Math.min(0.4, (phosphorus.priceIndex - 2.0) * 0.05);
    const priceAccessPenalty = basePriceImpact * (0.5 + region.resourceVulnerability * 0.5);
    foodSecurity -= priceAccessPenalty;
  }

  // Temperature stress (vulnerable regions hit harder)
  const tempAnomaly = resources.co2.temperatureAnomaly;
  if (tempAnomaly > 1.5) {
    const baseClimateImpact = (tempAnomaly - 1.5) * 0.15;
    const climatePenalty = baseClimateImpact * (0.5 + region.climateVulnerability * 0.5);
    foodSecurity -= climatePenalty;
  }

  // ... (biodiversity, AI enhancement, tech deployment)

  return Math.max(0, Math.min(1.5, foodSecurity));
}
```

