      // Regional food security (Oct 25, 2025 - regionalized)
      foodSecurity: 0.95,                  // Very high (resource-rich, breadbasket)

      // Crisis impacts
      monthlyExcessDeaths: 0,
      cumulativeCrisisDeaths: 0,
      refugeeBurden: 0,
