/**
 * Calculate REGIONAL food security (Oct 25, 2025)
 *
 * Food insecurity in one region doesn't always fully propagate to others.
 * Regions vary by:
 * - Local production vs import dependency
 * - Infrastructure relative to regional baseline
 * - Exposure to climate/water/biodiversity crises
 *
 * Research basis:
 * - FAO (2023): Regional food systems vary by trade integration
 * - IPCC AR6 (2022): Climate impacts vary by region
 * - Tainter (1988): Infrastructure complexity scales with population
 */
export function calculateRegionalFoodSecurity(
  state: GameState,
  region: { name: string; population: number; baselinePopulation: number; climateVulnerability: number; resourceVulnerability: number }
): number {
  const resources = state.resourceEconomy;
  const phosphorus = state.phosphorusSystem;
  const ocean = state.oceanAcidificationSystem;
  const freshwater = state.freshwaterSystem;

  // Base food availability from GLOBAL resource stocks
  // (All regions share global commodity markets to some degree)
  let foodSecurity = Math.min(1.0, resources.food.reserves);

  // REGIONAL infrastructure penalty (FIX Oct 25, 2025)
  // Infrastructure capacity scales with REGIONAL population, not global
  // Compare current population to 2025 baseline
  const regionalPopulationRatio = region.population / region.baselinePopulation;
  const infrastructurePenalty = Math.min(1.0, Math.max(0.3, regionalPopulationRatio));
  foodSecurity *= infrastructurePenalty;

  // GLOBAL crises (affect all regions but weighted by vulnerability)

  // Phosphorus depletion (affects all agriculture globally)
  if (phosphorus && phosphorus.reserves < 0.50) {
    const depletionPenalty = (0.50 - phosphorus.reserves) * 0.8;
    foodSecurity -= depletionPenalty;
  }

  // Phosphorus price crisis (import-dependent regions hit harder)
  if (phosphorus && phosphorus.priceIndex > 2.0) {
    const basePriceImpact = Math.min(0.4, (phosphorus.priceIndex - 2.0) * 0.05);
    const priceAccessPenalty = basePriceImpact * (0.5 + region.resourceVulnerability * 0.5);
    foodSecurity -= priceAccessPenalty;
  }

  // Ocean acidification (coastal/fish-dependent regions hit harder)
  if (ocean && ocean.marineFoodWebCollapseActive) {
    // Assume fish dependency correlates with resourceVulnerability
    const regionalFishDependence = region.resourceVulnerability * 0.375;
    const fishDependentPenalty = ocean.fishDependentImpact * regionalFishDependence;
    foodSecurity -= fishDependentPenalty;
  }

  // Freshwater stress (agricultural regions hit harder)
  if (freshwater && freshwater.waterStress > 0.50) {
    const baseWaterImpact = (freshwater.waterStress - 0.50) * 0.6;
    const waterPenalty = baseWaterImpact * (0.5 + region.climateVulnerability * 0.5);
    foodSecurity -= waterPenalty;
  }

  // Temperature stress (vulnerable regions hit harder)
  const tempAnomaly = resources.co2.temperatureAnomaly;
  if (tempAnomaly > 1.5) {
    const baseClimateImpact = (tempAnomaly - 1.5) * 0.15;
    const climatePenalty = baseClimateImpact * (0.5 + region.climateVulnerability * 0.5);
    foodSecurity -= climatePenalty;
  }

  // Biodiversity loss (global impact, but regions with more natural systems hit harder)
  if (state.biodiversitySystem) {
    const globalBio = state.biodiversitySystem.globalBiodiversityIndex;
    const vulnerabilityMultiplier = 0.7 + region.climateVulnerability * 0.3;

    if (globalBio < 0.80) {
      const pollinatorLoss = 0.80 - globalBio;
      const pollinationPenalty = pollinatorLoss * 0.35 * vulnerabilityMultiplier;
      foodSecurity -= pollinationPenalty;
    }

    if (globalBio < 0.60) {
      const soilHealthLoss = 0.60 - globalBio;
      const soilPenalty = soilHealthLoss * 0.25 * vulnerabilityMultiplier;
      foodSecurity -= soilPenalty;
    }

    if (globalBio < 0.50) {
      const pestControlLoss = 0.50 - globalBio;
      const pestPenalty = pestControlLoss * 0.20 * vulnerabilityMultiplier;
      foodSecurity -= pestPenalty;
    }
  }

  // AI enhancement (global technology, available to all regions)
  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  if (totalAI > 1.5 && avgAlignment > 0.7) {
    const aiAgriculture = Math.min(0.3, (totalAI - 1.5) * 0.1);
    foodSecurity += aiAgriculture;
  }

  // Breakthrough technologies (global deployment, available to all regions)
  const getTech = require('../techTree/helpers').isTechDeployed;
  const verticalFarming = getTech(state, 'vertical_farming');
  foodSecurity += verticalFarming * 0.25;

  const circularFood = getTech(state, 'circular_food_systems');
  foodSecurity += circularFood * 0.15;

  // Legacy support
  const sustainableAg = getTech(state, 'sustainableAgriculture');
  if (sustainableAg > 0 && verticalFarming === 0) {
    foodSecurity += sustainableAg * 0.3;
  }

  return Math.max(0, Math.min(1.5, foodSecurity));
}

