    65→ * - Phosphorus depletion, ocean collapse, water stress, temperature all affect food
    66→ */
    67→export function calculateFoodSecurity(state: GameState): number {
    68→  const resources = state.resourceEconomy;
    69→  const phosphorus = state.phosphorusSystem;
    70→  const ocean = state.oceanAcidificationSystem;
    71→  const freshwater = state.freshwaterSystem;
    72→
    73→  // Base food availability from resource stocks
    74→  let foodSecurity = Math.min(1.0, resources.food.reserves);
    75→
    76→  // FIX (Oct 25, 2025 FINAL): Infrastructure penalty is CURRENT capacity, not monthly degradation
    77→  // Applied to BASE calculation (recalculated monthly) to reflect current population
    78→  // Research: Tainter (1988) - complexity requires minimum population to maintain
    79→  const populationRatio = state.humanPopulationSystem.population / 8.0; // 8B baseline
    80→  const infrastructurePenalty = Math.min(1.0, Math.max(0.3, populationRatio)); // 30%-100% capacity
    81→  foodSecurity *= infrastructurePenalty;
    82→
    83→  // === PHOSPHORUS DEPLETION ===
    84→  // Low reserves = reduced agricultural yields
    85→  if (phosphorus && phosphorus.reserves < 0.50) {
    86→    const depletionPenalty = (0.50 - phosphorus.reserves) * 0.8;
    87→    foodSecurity -= depletionPenalty;
    88→  }
    89→
    90→  // High phosphorus prices = food price crisis (access problem)
    91→  // Research: 2007-08 food crisis saw 4x prices, 40M+ pushed into poverty
    92→  if (phosphorus && phosphorus.priceIndex > 2.0) {
    93→    const priceAccessPenalty = Math.min(0.4, (phosphorus.priceIndex - 2.0) * 0.05);
    94→    foodSecurity -= priceAccessPenalty;
    95→  }
    96→
    97→  // === OCEAN ACIDIFICATION ===
    98→  // Marine food web collapse affects 3 billion fish-dependent people
    99→  // Research: 37.5% of global population relies on fish as primary protein
   100→  if (ocean && ocean.marineFoodWebCollapseActive) {
   101→    const fishDependentPenalty = ocean.fishDependentImpact * 0.375;
   102→    foodSecurity -= fishDependentPenalty;
   103→  }
   104→
   105→  // === FRESHWATER STRESS ===
   106→  // Agriculture uses 70% of freshwater - stress directly impacts food production
   107→  if (freshwater && freshwater.waterStress > 0.50) {
   108→    const waterPenalty = (freshwater.waterStress - 0.50) * 0.6;
   109→    foodSecurity -= waterPenalty;
   110→  }
   111→
   112→  // === TEMPERATURE STRESS ===
   113→  // Research: Each 1°C above 1.5°C reduces crop yields 10-15%
   114→  // Major crops (wheat, rice, maize) have temperature optima
   115→  const tempAnomaly = resources.co2.temperatureAnomaly;
   116→  if (tempAnomaly > 1.5) {
   117→    const climatePenalty = (tempAnomaly - 1.5) * 0.15; // 15% per degree
   118→    foodSecurity -= climatePenalty;
   119→  }
   120→
   121→  // === BIODIVERSITY LOSS ===
   122→  // Research: IPBES (2016), Bardgett & van der Putten (2014), FAO soil reports
   123→  // Biodiversity loss affects food security through multiple pathways:
   124→  // 1. Pollinator decline (35% of crops depend on animal pollinators)
   125→  // 2. Soil health degradation (95% of food comes from soil)
   126→  // 3. Loss of natural pest control
   127→  if (state.biodiversitySystem) {
   128→    const globalBio = state.biodiversitySystem.globalBiodiversityIndex;
   129→
   130→    // Pollination crisis
   131→    // IPBES: 35% of global food crops depend on pollinators
   132→    // Threshold at 80% biodiversity (pollinators decline faster than general biodiversity)
   133→    if (globalBio < 0.80) {
   134→      const pollinatorLoss = 0.80 - globalBio;
   135→      const pollinationPenalty = pollinatorLoss * 0.35; // Up to 35% loss at bio=45%
   136→      foodSecurity -= pollinationPenalty;
   137→    }
   138→
   139→    // Soil health degradation
   140→    // Microbiomes, decomposers, nutrient cycling
   141→    // 95% of food comes from soil
   142→    if (globalBio < 0.60) {
   143→      const soilHealthLoss = 0.60 - globalBio;
   144→      const soilPenalty = soilHealthLoss * 0.25; // Up to 25% loss at bio=35%
   145→      foodSecurity -= soilPenalty;
   146→    }
   147→
   148→    // Natural pest control loss
   149→    // Without predators: 20-30% higher crop losses
   150→    if (globalBio < 0.50) {
   151→      const pestControlLoss = 0.50 - globalBio;
   152→      const pestPenalty = pestControlLoss * 0.20; // Up to 20% loss at bio=30%
   153→      foodSecurity -= pestPenalty;
   154→    }
   155→  }
   156→
   157→  // === AI ENHANCEMENT ===
   158→  // Aligned superintelligent AI can help food production
   159→  // Precision agriculture, vertical farms, synthetic biology
   160→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   161→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
   162→  if (totalAI > 1.5 && avgAlignment > 0.7) {
   163→    const aiAgriculture = Math.min(0.3, (totalAI - 1.5) * 0.1);
   164→    foodSecurity += aiAgriculture;
   165→  }
   166→
   167→  // === BREAKTHROUGH TECHNOLOGY ===
   168→  // FIX (Oct 25, 2025): Integrate ALL food technologies, not just one
   169→
   170→  // Vertical Farming - High-density indoor agriculture
   171→  const verticalFarming = getTechDeploymentSafe(state, 'vertical_farming');
   172→  foodSecurity += verticalFarming * 0.25; // Up to +25% (year-round, weather-independent)
   173→
   174→  // Circular Food Systems - Waste recycling, closed-loop nutrients
   175→  const circularFood = getTechDeploymentSafe(state, 'circular_food_systems');
   176→  foodSecurity += circularFood * 0.15; // Up to +15% (reduce waste, improve efficiency)
   177→
   178→  // Legacy support: sustainableAgriculture maps to vertical_farming in old system
   179→  const sustainableAg = getTechDeploymentSafe(state, 'sustainableAgriculture');
   180→  if (sustainableAg > 0 && verticalFarming === 0) {
   181→    // Only apply if new tech not deployed (avoid double-counting)
   182→    foodSecurity += sustainableAg * 0.3;
   183→  }
   184→
   185→  const finalFoodSec = Math.max(0, Math.min(1.5, foodSecurity));
   186→
   187→  // DEBUG: Log food security calculation every 12 months
   188→  if (state.currentMonth % 12 === 0) {
   189→    console.log(`  [QoL Phase] Food Security BASE Calc (Month ${state.currentMonth}): ${(finalFoodSec * 100).toFixed(1)}% | Tech: vf=${(verticalFarming * 100).toFixed(0)}% cf=${(circularFood * 100).toFixed(0)}% (infra penalty now in degradation phase)`);
   190→  }
   191→
