    17→export class FamineSystemPhase implements SimulationPhase {
    18→  readonly id = 'famine_system';
    19→  readonly name = 'Famine System';
    20→  readonly order = 21.5;
    21→
    22→  execute(state: GameState, rng: RNGFunction, context: PhaseContext): PhaseResult {
