import { RegionalPopulation } from '@/types/population';
import { getTechDeploymentSafe } from './techTree/helpers';

/**
 * Ensure regional death tracking fields exist (backward compatibility)
 *
 * Oct 26, 2025: Regional-First Architecture refactoring
 * Regional populations now track deaths directly (in millions)
 * Global totals are pure aggregations of regional values
 */
function ensureRegionalDeathTracking(region: RegionalPopulation): void {
  // @ts-expect-error - checking for optional fields added in refactoring
  if (!region.deathsByCategory) {
    // @ts-expect-error - initializing new fields
    region.deathsByCategory = {
      war: 0,
      famine: 0,
      disasters: 0,
      disease: 0,
      ecosystem: 0,
      pollution: 0,
      ai: 0,
      cascade: 0,
      other: 0
    };
  }

  // @ts-expect-error - checking for optional fields added in refactoring
  if (!region.deathsByRootCause) {
    // @ts-expect-error - initializing new fields
    region.deathsByRootCause = {
      climate: 0,
      conflict: 0,
      resource: 0,
      pollution: 0,
      ecosystem: 0,
      inequality: 0,
      social: 0,
      ai: 0
    };
  }
}

