     1→/**
     2→ * Famine System Phase (TIER 1.7)
     3→ *
     4→ * Manages realistic famine progression and ecosystem collapse famines
     5→ * - Checks regional biodiversity for ecosystem collapse → famine triggers
     6→ * - Updates active famines with gradual 30-60 day death curves
     7→ * - Applies famine deaths to population
     8→ * - Tracks tech deployment effectiveness vs genocide scenarios
     9→ *
    10→ * Research: Gaza/Yemen/Sudan (2024-25), IPBES (2019), FAO (2024)
    11→ *
    12→ * Order: 21.5 (after planetary boundaries 21.0, before extinctions 37.0)
    13→ */
    14→
    15→import { GameState, SimulationPhase, PhaseResult, PhaseContext, RNGFunction } from '@/types/game';
    16→
    17→export class FamineSystemPhase implements SimulationPhase {
    18→  readonly id = 'famine_system';
    19→  readonly name = 'Famine System';
    20→  readonly order = 21.5;
    21→
    22→  execute(state: GameState, rng: RNGFunction, context: PhaseContext): PhaseResult {
    23→    if (!state.famineSystem) return { events: [] };
    24→
    25→    // 1. Check regional biodiversity for new famine triggers (ecosystem collapse)
    26→    const { checkRegionalFamineRisk } = require('../../qualityOfLife');
    27→    checkRegionalFamineRisk(state, state.currentMonth);
    28→
    29→    // 2. Update active famines (progress death curves)
