    13→import { GameState, SimulationPhase, PhaseResult, PhaseContext, RNGFunction } from '@/types/game';
    14→
    15→export class HumanPopulationPhase implements SimulationPhase {
    16→  readonly id = 'human_population';
    17→  readonly name = 'Human Population Dynamics';
    18→  readonly order = 20.5;
    19→
    20→  execute(state: GameState, _rng: RNGFunction): PhaseResult {
    21→    // Population updates run once per simulation step (once per month)
    22→    // Each engine.step() represents one month advancing
    23→    // Population calculations use monthly rates - no need to gate on day
    24→    const {
    25→      updateHumanPopulation,
    26→      applyPopulationEffectsToQoL,
    27→      updateOutcomeMetricsWithPopulation
    28→    } = require('../../populationDynamics');
    29→
    30→    const {
