      resourceVulnerability: 0.8,          // Heavy food imports
      conflictRisk: 0.7,                   // Wars, civil conflicts

      // Regional food security (Oct 25, 2025 - regionalized)
      foodSecurity: 0.65,                  // Low (import-dependent, water scarcity, conflict)

      // Crisis impacts
