  // Category 2: Moderate AIs (30% - 6 agents)
  // Smaller labs, startups, varying quality
  for (let i = 0; i < 6; i++) {
    const alignment = 0.55 + Math.random() * 0.25; // 0.55-0.80
    aiAgents.push(createAIAgent(`moderate_${i}`, `Moderate-${i}`, 0.05 + i * 0.01, alignment, (i + 8) * 1.3));
