      ...(overrides.globalMetrics || {})
    },
    config: {
      ...baseState.config,
      ...(overrides.config || {})
    }
  };

  // Wrap with validation proxy in dev mode (zero overhead in production)
  return wrapStateForValidation(initialState);
}

